WITH profit_by_customer AS (SELECT cs.cs_bill_addr_sk, ca.ca_city, ca.ca_state, ca.ca_country, SUM(cs.cs_net_profit) AS customer_profit, SUM(cs.cs_ext_sales_price) AS customer_sales, SUM(cs.cs_quantity) AS total_quantity, COUNT(DISTINCT cs.cs_order_number) AS order_cnt FROM catalog_sales cs JOIN customer_address ca ON cs.cs_bill_addr_sk = ca.ca_address_sk GROUP BY cs.cs_bill_addr_sk, ca.ca_city, ca.ca_state, ca.ca_country), preferred_ship_mode AS (SELECT bill_addr_sk, sm_type, ROW_NUMBER() OVER (PARTITION BY bill_addr_sk ORDER BY mode_cnt DESC) AS rn FROM (SELECT cs.cs_bill_addr_sk AS bill_addr_sk, sm.sm_type, COUNT(*) AS mode_cnt FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY cs.cs_bill_addr_sk, sm.sm_type) t) SELECT p.cs_bill_addr_sk, p.ca_city, p.ca_state, p.ca_country, p.customer_profit, p.customer_sales, p.total_quantity, p.order_cnt, CASE WHEN p.customer_profit >= 20000 THEN 'Platinum' WHEN p.customer_profit >= 10000 THEN 'Gold' WHEN p.customer_profit >= 5000 THEN 'Silver' ELSE 'Bronze' END AS tier, ROW_NUMBER() OVER (ORDER BY p.customer_profit DESC) AS profit_rank, SUM(p.customer_profit) OVER (ORDER BY p.customer_profit DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_profit, m.sm_type AS preferred_ship_mode FROM profit_by_customer p LEFT JOIN preferred_ship_mode m ON p.cs_bill_addr_sk = m.bill_addr_sk AND m.rn = 1 ORDER BY p.customer_profit DESC LIMIT 5
